<?php
$badgeTone = static function ($status) {
  if ($status === 'ready_for_delivery' || $status === 'delivered') return 'is-success';
  if (in_array($status, ['waiting_parts', 'waiting_customer_approval'], true)) return 'is-warning';
  if (in_array($status, ['cancelled', 'unable_to_repair'], true)) return 'is-danger';
  return 'is-info';
};
$accessoryLabels = ['sim'=>'سیم‌کارت','case'=>'قاب','charger'=>'شارژر','cable'=>'کابل','memory_card'=>'کارت حافظه','box'=>'جعبه','other'=>'سایر'];
