$accessories = json_decode((string) ($repair['accessories'] ?? ''), true) ?: [];
$conditions = json_decode((string) ($repair['condition_flags'] ?? ''), true) ?: [];
$revealedPattern = [];
if (($revealedPassword['type'] ?? '') === 'pattern') {
  try { $revealedPattern = \Proma\Plugins\Repair\Support\PatternLock::nodes((string) ($revealedPassword['value'] ?? '')); } catch (\Throwable $ignored) { $revealedPattern = []; }
}
