      <form method="post" action="<?= e(url('plugin/repair/warranty/' . (int) $repair['id'])) ?>" class="pr-grid four"><?= csrf_field() ?><label class="pr-check"><input type="checkbox" name="enabled" value="1"<?= checked($warranty['enabled'] ?? 0, 1) ?>> فعال</label><label class="pr-field"><span>مدت (روز)</span><input name="warranty_days" type="number" min="0" max="3650" value="<?= (int) ($warranty['warranty_days'] ?? 0) ?>"></label><label class="pr-field"><span>شروع</span><input name="starts_at" data-jalali-input autocomplete="off" value="<?= e(!empty($warranty['starts_at']) ? jdate($warranty['starts_at']) : '') ?>"></label><label class="pr-field"><span>پایان</span><input name="ends_at" data-jalali-input autocomplete="off" value="<?= e(!empty($warranty['ends_at']) ? jdate($warranty['ends_at']) : '') ?>"></label><label class="pr-field pr-span-all"><span>شرایط</span><textarea name="conditions"><?= e($warranty['conditions'] ?? '') ?></textarea></label><button class="btn secondary">ذخیره گارانتی</button></form>
