<?php if ($revealedPassword): ?>
  <div class="modal pr-secret-modal" id="repair-device-password-modal" aria-describedby="repair-device-password-help">
    <div class="modal-content">
      <div class="modal-header"><div><h3>رمز دستگاه</h3><p id="repair-device-password-help">این اطلاعات حساس فقط در همین نوبت نمایش داده می‌شود؛ مشاهده در ممیزی ثبت شد.</p></div><button class="icon-btn" type="button" data-close-modal aria-label="بستن">×</button></div>
      <div class="modal-body">
        <?php if (($revealedPassword['type'] ?? '') === 'pattern' && $revealedPattern): ?>
          <?php $patternPoints = array_map(static function ($node) { $n = $node - 1; return (($n % 3) * 100 + 50) . ',' . ((int) floor($n / 3) * 100 + 50); }, $revealedPattern); ?>
          <div class="pr-alert pr-pattern-reveal"><strong>الگوی قفل دستگاه</strong><div class="pr-pattern-stage"><svg class="pr-pattern-lines" viewBox="0 0 300 300" aria-hidden="true"><polyline points="<?= e(implode(' ', $patternPoints)) ?>"></polyline></svg><div class="pr-pattern-grid"><?php for ($node=1; $node<=9; $node++): $step = array_search($node, $revealedPattern, true); ?><span class="<?= $step !== false ? 'is-selected' : '' ?>"><i><?= $node ?></i><?php if ($step !== false): ?><em><?= (int) $step + 1 ?></em><?php endif; ?></span><?php endfor; ?></div></div></div>
        <?php else: ?>
          <div class="pr-secret-value"><span><?= e(($revealedPassword['type'] ?? '') === 'pin' ? 'PIN دستگاه' : 'رمز دستگاه') ?></span><strong dir="ltr"><?= e($revealedPassword['value'] ?? '') ?></strong></div>
        <?php endif; ?>
      </div>
      <div class="modal-footer"><button class="btn secondary" type="button" data-close-modal>بستن</button></div>
    </div>
  </div>
<?php endif; ?>
